import random

def kth_largest(nums: list[int], k: int) -> int:
    """
    Returns the k-th largest element in an unsorted list using the Quickselect algorithm.
    Average time complexity: O(n), where n is the number of elements in the list.
    Worst case time complexity: O(n^2), which occurs when the pivot is the smallest or largest element consistently.
    """

    def partition(left: int, right: int, pivot_index: int) -> int:
        pivot_value = nums[pivot_index]
        # Move pivot to end
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        store_index = left
        for i in range(left, right):
            if nums[i] > pivot_value:  # We want the k-th largest, hence > instead of <
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1
        # Move pivot to its final place
        nums[right], nums[store_index] = nums[store_index], nums[right]
        return store_index

    def select(left: int, right: int, k_smallest: int) -> int:
        if left == right:
            return nums[left]
        pivot_index = random.randint(left, right)
        pivot_index = partition(left, right, pivot_index)
        if k_smallest == pivot_index:
            return nums[k_smallest]
        elif k_smallest < pivot_index:
            return select(left, pivot_index - 1, k_smallest)
        else:
            return select(pivot_index + 1, right, k_smallest)

    return select(0, len(nums) - 1, k - 1)

import random

def kth_largest(nums: list[int], k: int) -> int:
    """
    Returns the k-th largest element in an unsorted list using the Median of Medians algorithm.
    Average time complexity: O(n), worst-case time complexity: O(n) as well.
    """

    def partition(nums, left, right, pivot_index):
        pivot_value = nums[pivot_index]
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        store_index = left
        for i in range(left, right):
            if nums[i] > pivot_value:
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1
        nums[right], nums[store_index] = nums[store_index], nums[right]
        return store_index

    def median_of_medians(nums, left, right, k):
        if right - left + 1 <= 5:
            return sorted(nums[left:right + 1])[k - 1]

        for i in range(left, right + 1, 5):
            sub_right = min(i + 4, right)
            median_idx = (i + sub_right) // 2
            nums[left + (i - left) // 5] = sorted(nums[i:sub_right + 1])[ (sub_right - i) // 2 ]

        mid_index = (right - left) // 10 + left
        pivot = median_of_medians(nums, left, left + (right - left) // 5, mid_index)

        pivot_index = partition(nums, left, right, nums.index(pivot))

        if k - 1 == pivot_index:
            return nums[pivot_index]
        elif k - 1 < pivot_index:
            return median_of_medians(nums, left, pivot_index - 1, k)
        else:
            return median_of_medians(nums, pivot_index + 1, right, k)

    return median_of_medians(nums, 0, len(nums) - 1, k)

def kth_largest(nums: list[int], k: int) -> int:
    """
    Returns the k-th largest element in an unsorted list using the Introselect algorithm.
    Average time complexity: O(n), worst-case time complexity: O(n log n).
    """

    def partition(left: int, right: int, pivot_index: int) -> int:
        pivot_value = nums[pivot_index]
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        store_index = left
        for i in range(left, right):
            if nums[i] > pivot_value:  # Change to > for the k-th largest
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1
        nums[right], nums[store_index] = nums[store_index], nums[right]
        return store_index

    def introselect(left: int, right: int, k_smallest: int, depth_limit: int) -> int:
        if left == right:
            return nums[left]
        if depth_limit == 0:
            nums[left:right + 1] = sorted(nums[left:right + 1])  # Fall back to sorting
            return nums[left + k_smallest]

        pivot_index = left + (right - left) // 2
        pivot_index = partition(left, right, pivot_index)

        if k_smallest == pivot_index:
            return nums[k_smallest]
        elif k_smallest < pivot_index:
            return introselect(left, pivot_index - 1, k_smallest, depth_limit - 1)
        else:
            return introselect(pivot_index + 1, right, k_smallest, depth_limit - 1)

    import math
    depth_limit = math.floor(math.log(len(nums), 2)) * 2  # Depth limit to avoid worst-case
    return introselect(0, len(nums) - 1, k - 1, depth_limit)
